-- Lumora initial MySQL 8 schema. Flyway records this migration after a successful run.
CREATE TABLE schools (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, code VARCHAR(30) NOT NULL UNIQUE, registration_number VARCHAR(255), county VARCHAR(255), address VARCHAR(255), phone VARCHAR(255), email VARCHAR(255), created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT);
CREATE TABLE academic_years (id BIGINT AUTO_INCREMENT PRIMARY KEY, school_id BIGINT NOT NULL, name VARCHAR(20) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, active BOOLEAN NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, UNIQUE(school_id,name), FOREIGN KEY(school_id) REFERENCES schools(id));
CREATE TABLE terms (id BIGINT AUTO_INCREMENT PRIMARY KEY, academic_year_id BIGINT NOT NULL, term_number INT NOT NULL, name VARCHAR(40) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, active BOOLEAN NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, UNIQUE(academic_year_id,term_number), FOREIGN KEY(academic_year_id) REFERENCES academic_years(id));
CREATE TABLE school_classes (id BIGINT AUTO_INCREMENT PRIMARY KEY, school_id BIGINT NOT NULL, name VARCHAR(40) NOT NULL, level INT NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, UNIQUE(school_id,name), FOREIGN KEY(school_id) REFERENCES schools(id));
CREATE TABLE class_streams (id BIGINT AUTO_INCREMENT PRIMARY KEY, school_class_id BIGINT NOT NULL, name VARCHAR(40) NOT NULL, capacity INT, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, UNIQUE(school_class_id,name), FOREIGN KEY(school_class_id) REFERENCES school_classes(id));
CREATE TABLE subjects (id BIGINT AUTO_INCREMENT PRIMARY KEY, school_id BIGINT NOT NULL, code VARCHAR(20) NOT NULL, name VARCHAR(100) NOT NULL, compulsory BOOLEAN NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, UNIQUE(school_id,code), FOREIGN KEY(school_id) REFERENCES schools(id));
CREATE TABLE roles (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(40) NOT NULL UNIQUE, description VARCHAR(255), created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT);
CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, email VARCHAR(150) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, enabled BOOLEAN NOT NULL, locked BOOLEAN NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT);
CREATE TABLE user_roles (user_id BIGINT NOT NULL, role_id BIGINT NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE teachers (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE, employee_number VARCHAR(30) NOT NULL UNIQUE, first_name VARCHAR(80) NOT NULL, last_name VARCHAR(80) NOT NULL, gender VARCHAR(10), phone VARCHAR(255), tsc_number VARCHAR(255), employment_date DATE, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE parents (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNIQUE, first_name VARCHAR(80) NOT NULL, last_name VARCHAR(80) NOT NULL, phone VARCHAR(30) NOT NULL, national_id VARCHAR(255), email VARCHAR(255), occupation VARCHAR(255), created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE students (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNIQUE, school_id BIGINT NOT NULL, admission_number VARCHAR(30) NOT NULL UNIQUE, first_name VARCHAR(80) NOT NULL, middle_name VARCHAR(255), last_name VARCHAR(80) NOT NULL, gender VARCHAR(10) NOT NULL, date_of_birth DATE NOT NULL, admission_date DATE, birth_certificate_number VARCHAR(255), national_id VARCHAR(255), county VARCHAR(255), photo_path VARCHAR(255), active BOOLEAN NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(school_id) REFERENCES schools(id));
CREATE TABLE student_guardians (id BIGINT AUTO_INCREMENT PRIMARY KEY, student_id BIGINT NOT NULL, parent_id BIGINT NOT NULL, relationship VARCHAR(30) NOT NULL, primary_contact BOOLEAN NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, UNIQUE(student_id,parent_id), FOREIGN KEY(student_id) REFERENCES students(id), FOREIGN KEY(parent_id) REFERENCES parents(id));
CREATE TABLE student_enrollments (id BIGINT AUTO_INCREMENT PRIMARY KEY, student_id BIGINT NOT NULL, academic_year_id BIGINT NOT NULL, class_stream_id BIGINT NOT NULL, active BOOLEAN NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, UNIQUE(student_id,academic_year_id), FOREIGN KEY(student_id) REFERENCES students(id), FOREIGN KEY(academic_year_id) REFERENCES academic_years(id), FOREIGN KEY(class_stream_id) REFERENCES class_streams(id));
CREATE TABLE teacher_subject_assignments (id BIGINT AUTO_INCREMENT PRIMARY KEY, teacher_id BIGINT NOT NULL, subject_id BIGINT NOT NULL, class_stream_id BIGINT NOT NULL, term_id BIGINT NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, UNIQUE(teacher_id,subject_id,class_stream_id,term_id), FOREIGN KEY(teacher_id) REFERENCES teachers(id), FOREIGN KEY(subject_id) REFERENCES subjects(id), FOREIGN KEY(class_stream_id) REFERENCES class_streams(id), FOREIGN KEY(term_id) REFERENCES terms(id));
CREATE TABLE attendance_sessions (id BIGINT AUTO_INCREMENT PRIMARY KEY, class_stream_id BIGINT NOT NULL, teacher_id BIGINT NOT NULL, attendance_date DATE NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, UNIQUE(class_stream_id,attendance_date), FOREIGN KEY(class_stream_id) REFERENCES class_streams(id), FOREIGN KEY(teacher_id) REFERENCES teachers(id));
CREATE TABLE attendance_records (id BIGINT AUTO_INCREMENT PRIMARY KEY, attendance_session_id BIGINT NOT NULL, student_id BIGINT NOT NULL, status VARCHAR(15) NOT NULL, remarks VARCHAR(255), created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, UNIQUE(attendance_session_id,student_id), FOREIGN KEY(attendance_session_id) REFERENCES attendance_sessions(id), FOREIGN KEY(student_id) REFERENCES students(id));
CREATE TABLE grading_scales (id BIGINT AUTO_INCREMENT PRIMARY KEY, school_id BIGINT NOT NULL, name VARCHAR(80) NOT NULL, active BOOLEAN NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, UNIQUE(school_id,name), FOREIGN KEY(school_id) REFERENCES schools(id));
CREATE TABLE grade_definitions (id BIGINT AUTO_INCREMENT PRIMARY KEY, grading_scale_id BIGINT NOT NULL, grade VARCHAR(5) NOT NULL, minimum_mark DECIMAL(5,2) NOT NULL, maximum_mark DECIMAL(5,2) NOT NULL, points INT NOT NULL, remarks VARCHAR(100), created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, UNIQUE(grading_scale_id,grade), FOREIGN KEY(grading_scale_id) REFERENCES grading_scales(id));
CREATE TABLE examinations (id BIGINT AUTO_INCREMENT PRIMARY KEY, term_id BIGINT NOT NULL, class_stream_id BIGINT NOT NULL, grading_scale_id BIGINT NOT NULL, name VARCHAR(100) NOT NULL, examination_date DATE NOT NULL, published BOOLEAN NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, FOREIGN KEY(term_id) REFERENCES terms(id), FOREIGN KEY(class_stream_id) REFERENCES class_streams(id), FOREIGN KEY(grading_scale_id) REFERENCES grading_scales(id));
CREATE TABLE exam_subjects (id BIGINT AUTO_INCREMENT PRIMARY KEY, examination_id BIGINT NOT NULL, subject_id BIGINT NOT NULL, maximum_mark DECIMAL(6,2) NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, UNIQUE(examination_id,subject_id), FOREIGN KEY(examination_id) REFERENCES examinations(id), FOREIGN KEY(subject_id) REFERENCES subjects(id));
CREATE TABLE exam_results (id BIGINT AUTO_INCREMENT PRIMARY KEY, exam_subject_id BIGINT NOT NULL, student_id BIGINT NOT NULL, marks DECIMAL(6,2) NOT NULL, grade VARCHAR(5), points INT, remarks VARCHAR(255), created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, UNIQUE(exam_subject_id,student_id), FOREIGN KEY(exam_subject_id) REFERENCES exam_subjects(id), FOREIGN KEY(student_id) REFERENCES students(id));
CREATE TABLE fee_categories (id BIGINT AUTO_INCREMENT PRIMARY KEY, school_id BIGINT NOT NULL, name VARCHAR(100) NOT NULL, description VARCHAR(255), active BOOLEAN NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, UNIQUE(school_id,name), FOREIGN KEY(school_id) REFERENCES schools(id));
CREATE TABLE fee_structures (id BIGINT AUTO_INCREMENT PRIMARY KEY, term_id BIGINT NOT NULL, school_class_id BIGINT NOT NULL, currency_code VARCHAR(3) NOT NULL, active BOOLEAN NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, UNIQUE(term_id,school_class_id), FOREIGN KEY(term_id) REFERENCES terms(id), FOREIGN KEY(school_class_id) REFERENCES school_classes(id));
CREATE TABLE fee_structure_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, fee_structure_id BIGINT NOT NULL, fee_category_id BIGINT NOT NULL, amount DECIMAL(15,2) NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, UNIQUE(fee_structure_id,fee_category_id), FOREIGN KEY(fee_structure_id) REFERENCES fee_structures(id), FOREIGN KEY(fee_category_id) REFERENCES fee_categories(id));
CREATE TABLE student_invoices (id BIGINT AUTO_INCREMENT PRIMARY KEY, student_id BIGINT NOT NULL, term_id BIGINT NOT NULL, invoice_number VARCHAR(40) NOT NULL UNIQUE, total_amount DECIMAL(15,2) NOT NULL, balance_amount DECIMAL(15,2) NOT NULL, status VARCHAR(20) NOT NULL, due_date DATE NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, FOREIGN KEY(student_id) REFERENCES students(id), FOREIGN KEY(term_id) REFERENCES terms(id));
CREATE TABLE payments (id BIGINT AUTO_INCREMENT PRIMARY KEY, student_invoice_id BIGINT NOT NULL, receipt_number VARCHAR(40) NOT NULL UNIQUE, amount DECIMAL(15,2) NOT NULL, method VARCHAR(20) NOT NULL, paid_at DATETIME NOT NULL, reference_number VARCHAR(100), received_by_user_id BIGINT, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, FOREIGN KEY(student_invoice_id) REFERENCES student_invoices(id), FOREIGN KEY(received_by_user_id) REFERENCES users(id));
CREATE TABLE mpesa_transactions (id BIGINT AUTO_INCREMENT PRIMARY KEY, payment_id BIGINT NOT NULL UNIQUE, transaction_code VARCHAR(100) NOT NULL UNIQUE, payer_phone VARCHAR(30) NOT NULL, amount DECIMAL(15,2) NOT NULL, transaction_time DATETIME NOT NULL, account_reference VARCHAR(100), created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, FOREIGN KEY(payment_id) REFERENCES payments(id));
CREATE TABLE book_categories (id BIGINT AUTO_INCREMENT PRIMARY KEY, school_id BIGINT NOT NULL, name VARCHAR(100) NOT NULL, description VARCHAR(255), created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, UNIQUE(school_id,name), FOREIGN KEY(school_id) REFERENCES schools(id));
CREATE TABLE books (id BIGINT AUTO_INCREMENT PRIMARY KEY, book_category_id BIGINT NOT NULL, title VARCHAR(255) NOT NULL, author VARCHAR(150) NOT NULL, isbn VARCHAR(30) UNIQUE, publisher VARCHAR(255), publication_year INT, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, FOREIGN KEY(book_category_id) REFERENCES book_categories(id));
CREATE TABLE book_copies (id BIGINT AUTO_INCREMENT PRIMARY KEY, book_id BIGINT NOT NULL, accession_number VARCHAR(40) NOT NULL UNIQUE, status VARCHAR(30) NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, FOREIGN KEY(book_id) REFERENCES books(id));
CREATE TABLE book_loans (id BIGINT AUTO_INCREMENT PRIMARY KEY, book_copy_id BIGINT NOT NULL, user_id BIGINT NOT NULL, borrowed_on DATE NOT NULL, due_date DATE NOT NULL, returned_on DATE, status VARCHAR(15) NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, FOREIGN KEY(book_copy_id) REFERENCES book_copies(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE announcements (id BIGINT AUTO_INCREMENT PRIMARY KEY, created_by_user_id BIGINT NOT NULL, title VARCHAR(150) NOT NULL, content LONGTEXT NOT NULL, published_at DATETIME NOT NULL, expires_at DATETIME, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, FOREIGN KEY(created_by_user_id) REFERENCES users(id));
CREATE TABLE notifications (id BIGINT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(150) NOT NULL, message LONGTEXT NOT NULL, type VARCHAR(30) NOT NULL, sent_at DATETIME NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT);
CREATE TABLE notification_recipients (id BIGINT AUTO_INCREMENT PRIMARY KEY, notification_id BIGINT NOT NULL, user_id BIGINT NOT NULL, read_at DATETIME, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, UNIQUE(notification_id,user_id), FOREIGN KEY(notification_id) REFERENCES notifications(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE audit_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT, action VARCHAR(80) NOT NULL, entity_name VARCHAR(80) NOT NULL, entity_id BIGINT, ip_address VARCHAR(45), occurred_at DATETIME NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, version BIGINT, FOREIGN KEY(user_id) REFERENCES users(id));

CREATE INDEX idx_students_school ON students(school_id);
CREATE INDEX idx_enrollments_stream ON student_enrollments(class_stream_id);
CREATE INDEX idx_results_student ON exam_results(student_id);
CREATE INDEX idx_invoices_student ON student_invoices(student_id);
CREATE INDEX idx_payments_invoice ON payments(student_invoice_id);
